import { createHistoryTestResultLookup, } from "@allurereport/core-api";
import { createTreeByLabels, md5 } from "@allurereport/plugin-api";
import { isChildrenLeavesOnly } from "../chart-utils.js";
import { convertTreeDataToTreeMapNode, transformTreeMapNode } from "../treeMapUtils.js";
import { behaviorLabels, filterTestsWithBehaviorLabels } from "./utils/behavior.js";
const groupFactoryFn = (parentId, groupClassifier) => ({
    nodeId: md5((parentId ? `${parentId}.` : "") + groupClassifier),
    name: groupClassifier,
    value: 0,
    newCount: 0,
    deletedCount: 0,
    disabledCount: 0,
    enabledCount: 0,
});
const addLeafToGroupFn = (group, leaf) => {
    group.value += leaf.value;
    switch (leaf.changeType) {
        case "new":
            group.newCount++;
            break;
        case "deleted":
            group.deletedCount++;
            break;
        case "enabled":
            group.enabledCount++;
            break;
        case "disabled":
            group.disabledCount++;
            break;
    }
};
const calculateColorValue = (metrics) => {
    const netChange = metrics.newCount + metrics.enabledCount - (metrics.deletedCount + metrics.disabledCount);
    const normalizedChange = netChange / metrics.totalTests;
    return Math.max(0, Math.min(1, (normalizedChange + 1) / 2));
};
const isSkipped = (tr) => tr.status === "skipped";
const getNewTestResults = (trs, closestHtrs) => {
    return trs.filter((tr) => !closestHtrs[tr.retryHash]);
};
const getRemovedTestResults = (historyTestResults, matchedHistoryTestResults) => {
    return historyTestResults.filter((htr) => !matchedHistoryTestResults.has(htr));
};
const getEnabledTestResults = (trs, closestHtrs) => {
    return trs.filter((tr) => {
        const historyPointTestResult = closestHtrs[tr.retryHash];
        return historyPointTestResult && isSkipped(historyPointTestResult) && !isSkipped(tr);
    });
};
const getDisabledTestResults = (trs, closestHtrs) => {
    return trs.filter((tr) => {
        const historyPointTestResult = closestHtrs[tr.retryHash];
        return historyPointTestResult && !isSkipped(historyPointTestResult) && isSkipped(tr);
    });
};
const calculateSubtreeMetrics = (node) => {
    if (!node.children || node.children.length === 0) {
        const changeType = node?.changeType;
        return {
            totalTests: 1,
            newCount: changeType === "new" ? 1 : 0,
            deletedCount: changeType === "deleted" ? 1 : 0,
            disabledCount: changeType === "disabled" ? 1 : 0,
            enabledCount: changeType === "enabled" ? 1 : 0,
        };
    }
    let totalTests = 0;
    let newCount = 0;
    let deletedCount = 0;
    let disabledCount = 0;
    let enabledCount = 0;
    for (const child of node.children) {
        const childMetrics = calculateSubtreeMetrics(child);
        totalTests += childMetrics.totalTests;
        newCount += childMetrics.newCount;
        deletedCount += childMetrics.deletedCount;
        disabledCount += childMetrics.disabledCount;
        enabledCount += childMetrics.enabledCount;
    }
    return { totalTests, newCount, deletedCount, disabledCount, enabledCount };
};
const createCoverageDiffTreeMap = (trs, closestHtrs, historyTestResults = [], matchedHistoryTestResults = new Set()) => {
    const newTrs = getNewTestResults(trs, closestHtrs);
    const removedHtrs = getRemovedTestResults(historyTestResults, matchedHistoryTestResults);
    const enabledTrs = getEnabledTestResults(trs, closestHtrs);
    const disabledTrs = getDisabledTestResults(trs, closestHtrs);
    const newTestsById = new Map(newTrs.map((tr) => [tr.retryHash, tr]));
    const deletedTestsById = new Map(removedHtrs.map((htr) => [htr.retryHash, htr]));
    const enabledTestsById = new Map(enabledTrs.map((tr) => [tr.retryHash, tr]));
    const disabledTestsById = new Map(disabledTrs.map((tr) => [tr.retryHash, tr]));
    const allTests = [...trs, ...removedHtrs];
    const getChangeType = (retryHash) => {
        if (newTestsById.has(retryHash)) {
            return "new";
        }
        if (deletedTestsById.has(retryHash)) {
            return "deleted";
        }
        if (enabledTestsById.has(retryHash)) {
            return "enabled";
        }
        if (disabledTestsById.has(retryHash)) {
            return "disabled";
        }
        return "unchanged";
    };
    const leafFactoryFnWithMaps = (test) => {
        const changeType = getChangeType(test.retryHash);
        return {
            nodeId: test.id,
            name: test.name,
            value: 1,
            changeType,
        };
    };
    const treeByLabels = createTreeByLabels(allTests, behaviorLabels, leafFactoryFnWithMaps, groupFactoryFn, addLeafToGroupFn);
    const convertedTree = convertTreeDataToTreeMapNode(treeByLabels, (node, isGroup) => {
        const baseNode = {
            id: node.name,
            value: isGroup ? undefined : node.value,
        };
        if (isGroup) {
            const group = node;
            return {
                ...baseNode,
                newCount: group.newCount,
                deletedCount: group.deletedCount,
                disabledCount: group.disabledCount,
                enabledCount: group.enabledCount,
            };
        }
        else {
            const leaf = node;
            return {
                ...baseNode,
                changeType: leaf.changeType,
                newCount: leaf.changeType === "new" ? 1 : 0,
                deletedCount: leaf.changeType === "deleted" ? 1 : 0,
                disabledCount: leaf.changeType === "disabled" ? 1 : 0,
                enabledCount: leaf.changeType === "enabled" ? 1 : 0,
            };
        }
    }, () => ({
        id: "root",
        newCount: 0,
        deletedCount: 0,
        disabledCount: 0,
        enabledCount: 0,
    }));
    return transformTreeMapNode(convertedTree, (node) => {
        const subtreeMetrics = calculateSubtreeMetrics(node);
        const colorValue = calculateColorValue(subtreeMetrics);
        const { totalTests, ...restSubtreeMetrics } = subtreeMetrics;
        if (isChildrenLeavesOnly(node)) {
            return {
                ...node,
                value: totalTests,
                children: undefined,
                colorValue,
                ...restSubtreeMetrics,
            };
        }
        return {
            ...node,
            colorValue,
            ...restSubtreeMetrics,
        };
    });
};
export const coverageDiffTreeMapAccessor = {
    getTreeMap: ({ testResults, historyDataPoints, allTestResults }) => {
        const lookupHistoryTestResult = createHistoryTestResultLookup(allTestResults ?? testResults);
        const testsWithBehaviorLabels = filterTestsWithBehaviorLabels(testResults);
        if (!historyDataPoints || historyDataPoints.length === 0) {
            return createCoverageDiffTreeMap(testsWithBehaviorLabels, {});
        }
        const closestHdp = historyDataPoints[0];
        const closestHtrsWithBehaviorLabels = filterTestsWithBehaviorLabels(Object.values(closestHdp.testResults)).filter((tr) => {
            const selected = lookupHistoryTestResult(closestHdp, tr);
            return !selected || selected === tr;
        });
        const selectedHtrsByCurrentRetryHash = {};
        const matchedHistoryTestResults = new Set();
        for (const testResult of testsWithBehaviorLabels) {
            if (!testResult.retryHash) {
                continue;
            }
            const historicalTestResult = lookupHistoryTestResult(closestHdp, testResult);
            if (historicalTestResult) {
                selectedHtrsByCurrentRetryHash[testResult.retryHash] = historicalTestResult;
                matchedHistoryTestResults.add(historicalTestResult);
            }
        }
        return createCoverageDiffTreeMap(testsWithBehaviorLabels, selectedHtrsByCurrentRetryHash, closestHtrsWithBehaviorLabels, matchedHistoryTestResults);
    },
};
